begin;
set local search_path=public,extensions;
select plan(10);
select ok(not has_function_privilege('authenticated','public.operational_metrics_v1()','EXECUTE')and has_function_privilege('service_role','public.operational_metrics_v1()','EXECUTE'),'metrics snapshot is a narrow service-only RPC');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.record_operational_job_run_v1('P186_CRON',true,60,1234);
select is((select last_duration_ms from public.operational_heartbeats where service_code='P186_CRON'),1234,'cron duration is recorded numerically');
select is(public.operational_metrics_v1()->'services'@>'[{"service":"P186_CRON","healthy":true,"duration_ms":1234}]',true,'numeric metrics reflect actual heartbeat');
insert into public.event_outbox(aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key,attempt_count,locked_at,locked_by)values('test','p186-document','DocumentUploadedV1','f1860000-0000-4000-8000-000000000001','{"private":"never_export"}','p186-doc',7,clock_timestamp(),'f1860000-0000-4000-8000-000000000002'),('test','p186-other','OrganizationEmailInvitationRequestedV1','f1860000-0000-4000-8000-000000000003','{}','p186-other',0,clock_timestamp(),'f1860000-0000-4000-8000-000000000002');
select throws_ok($$select public.defer_outbox_document_dependency_v1((select id from public.event_outbox where idempotency_key='p186-doc'),'f1860000-0000-4000-8000-000000000099')$$,'55000','OUTBOX_DOCUMENT_CLAIM_NOT_OWNED','another worker cannot defer someone else''s claim');
select public.defer_outbox_document_dependency_v1((select id from public.event_outbox where idempotency_key='p186-doc'),'f1860000-0000-4000-8000-000000000002');
select ok((select attempt_count=7 and locked_by is null and available_at>clock_timestamp()+interval'50 seconds'and published_at is null and dead_lettered_at is null from public.event_outbox where idempotency_key='p186-doc'),'dependency outage preserves retry budget and defers without accepting document');
select throws_ok($$select public.defer_outbox_document_dependency_v1((select id from public.event_outbox where idempotency_key='p186-other'),'f1860000-0000-4000-8000-000000000002')$$,'55000','OUTBOX_DOCUMENT_CLAIM_NOT_OWNED','antivirus deferral cannot delay independent invitation');
select ok(public.operational_metrics_v1()::text not like'%never_export%'and public.operational_metrics_v1()::text not like'%p186-document%','metrics expose neither event payload nor aggregate identity');
select public.record_operational_job_run_v1('P186_CRON',false,60,1250);
select is(public.operational_metrics_v1()->'services'@>'[{"service":"P186_CRON","healthy":false}]',true,'failed cycle changes service metric');
select throws_ok($$select public.record_operational_job_run_v1('P186_CRON',true,60,-1)$$,'23514',null,'negative duration is rejected transactionally');
select ok((select healthy=false and last_duration_ms=1250 from public.operational_heartbeats where service_code='P186_CRON'),'invalid duration cannot refresh the prior unhealthy heartbeat');
select*from finish();
rollback;
